2	// Guard against the master-key disaster runbook drifting between its two copies:
3	//   - docs/operations/master-key-disaster-runbook.md   (canonical, engineering detail)
4	//   - sites/docs/.../operator/master-key-runbook.md     (published, operator-facing rewrite)
5	//
6	// The two are intentionally NOT identical (the site copy trims source file paths and
7	// migration versions), but the load-bearing facts — the golden rule and the
8	// quick-reference step ordering — must read the same everywhere an operator might land
9	// mid-incident. This extracts those anchors from the canonical doc and fails if the
10	// published copy doesn't contain them verbatim (modulo markdown line-wrap position).
11	
12	import { readFileSync } from 'node:fs';
13	import { join } from 'node:path';
14	
15	const root = new URL('..', import.meta.url).pathname;
16	const read = (path) => readFileSync(join(root, path), 'utf8');
17	const flatten = (text) => text.replace(/\s+/g, ' ').trim();
18	
19	const REPO_PATH = 'docs/operations/master-key-disaster-runbook.md';
20	const SITE_PATH = 'sites/docs/src/content/docs/operator/master-key-runbook.md';
21	
22	const repoFlat = flatten(read(REPO_PATH));
23	const siteFlat = flatten(read(SITE_PATH));
24	
25	const ANCHORS = [
26	  ['golden rule', /\*\*Back up the KEK[^*]*?\*\*/],
27	  ['loss-scenario ordering', /\*\*Loss:\*\*.*?repo-key rotation\./],
28	  ['compromise-scenario ordering', /\*\*Compromise:\*\*.*?repo-key rotation\./],
29	];
30	
31	let drifted = false;
32	for (const [label, regex] of ANCHORS) {
33	  const match = repoFlat.match(regex);
34	  if (!match) {
35	    console.error(`✗ runbook-parity: could not find the ${label} anchor in ${REPO_PATH}`);
36	    console.error('  (update the regex in scripts/runbook-parity-check.mjs if the wording changed intentionally)');
37	    drifted = true;
38	    continue;
39	  }
40	  if (!siteFlat.includes(match[0])) {
41	    console.error(`✗ runbook-parity: ${label} has drifted between the repo runbook and the published site page`);
42	    console.error(`  expected verbatim in ${SITE_PATH}:`);
43	    console.error(`  ${match[0]}`);
44	    drifted = true;
45	  }
46	}
47	
48	if (drifted) {
49	  console.error(
50	    `\nThe golden rule and quick-reference ordering must stay word-for-word identical between\n${REPO_PATH} and ${SITE_PATH} — update both together (see the note at the top of each).`,
51	  );
52	  process.exit(1);
53	}
